// Package faasschema binds the canonical schema to its embedded migration set.
package faasschema

import _ "embed"

// SQL is generated by cmd/schema-dump after applying every embedded migration.
//
//go:embed schema.sql
var canonicalSQL string

// MigrationSourceSHA256 changes when any embedded migration's bytes change.
//
//go:embed schema.sql.migrations.sha256
var migrationSourceSHA256 string

func CanonicalSQL() string          { return canonicalSQL }
func MigrationSourceSHA256() string { return migrationSourceSHA256 }
